mapper.update:
	/** saleson.shop.lclgvHnrUser.LclgvHnrUserMngMapper.updateLclgvHnrUserMng 지자체 명예 사용자 수정 */
		UPDATE G_LCLGV_HNR_USER_STNG_MNG SET
			GLD_GRD_DNTN_AMT = #{gldGrdDntnAmt}
			, SLVR_GRD_DNTN_AMT = #{slvrGrdDntnAmt}
			, BRNZ_GRD_DNTN_AMT = #{brnzGrdDntnAmt}
			, HNR_USER_STNG_TTL = #{hnrUserStngTtl}
         	, HNR_USER_RWRD = #{hnrUserRwrd}

            , RPRS_IMG_NM = #{rprsImgNm}

         	, HNR_USER_SLCTN_SE_CD = #{hnrUserSlctnSeCd}
         	, USE_YN = #{useYn}
			, LAST_REG_DT = SYS_DATETIME
         	, LAST_RGTR_ID = #{lastRgtrId}
		WHERE 1=1
      	AND LCLGV_CD = #{lclgvCd}

mapper.select:
/** saleson.shop.lclgvHnrUser.LclgvHnrUserMngMapper.selectLclgvHnrUserMngList 지자체 명예 사용자 목록 조회 */
SELECT ROW_NUMBER() OVER(ORDER BY LCLGV_CD) AS ROW_NUMBER , GL.UPPER_LOCGOV_CODE , GL.UPPER_LOCGOV_NM , A.LCLGV_CD , GL.LOCGOV_NM AS LCLGV_CD_NM , A.GLD_GRD_DNTN_AMT , A.SLVR_GRD_DNTN_AMT , A.BRNZ_GRD_DNTN_AMT , A.HNR_USER_RWRD , A.RPRS_IMG_NM , A.HNR_USER_SLCTN_SE_CD , B.LABEL AS HNR_USER_SLCTN_SE_CD_NM , A.USE_YN , A.last_reg_dt , A.last_rgtr_id FROM G_LCLGV_HNR_USER_STNG_MNG A, OP_COMMON_CODE B, G_LOCGOV GL WHERE A.HNR_USER_SLCTN_SE_CD = B.ID(+) AND A.LCLGV_CD = GL.LOCGOV_CODE(+)
AND LCLGV_CD = #{lclgvCd}
AND GL.UPPER_LOCGOV_CODE = #{upperLocgovCode}

/** saleson.shop.lclgvHnrUser.LclgvHnrUserMngMapper.selectLclgvHnrUserMngListCnt 지자체 명예 사용자 목록 카운트 조회 */
	SELECT	COUNT(LCLGV_CD)
	FROM	G_LCLGV_HNR_USER_STNG_MNG LHUS
			LEFT JOIN G_LOCGOV L ON LHUS.LCLGV_CD = L.LOCGOV_CODE
	WHERE	1 = 1

	AND LHUS.LCLGV_CD = #{lclgvCd}


	AND L.UPPER_LOCGOV_CODE = #{upperLocgovCode}

mapper.update:
UPDATE 	G_LCLGV_HNR_USER_STNG_MNG
SET 	RPRS_IMG_NM = ''
WHERE 	LCLGV_CD = #{lclgvCd}

mapper.select:
/* saleson.shop.lclgvHnrUser.LclgvHnrUserMngMapper.selectImgDescListByPrjId 지자체 명예 사용자 이미지 설명 조회 */
SELECT IMG_EXPLN AS PRJSVALUES
   ,IMG_SEQ AS PRJSINDEXES
FROM g_lclgv_hnr_user_rwrd_img_expln
WHERE lclgv_cd = #{lclgvCd}
ORDER BY IMG_SEQ ASC;

mapper.insert:
/* saleson.shop.lclgvHnrUser.LclgvHnrUserMngMapper.insertImgDescList 지자체 명예 사용자 이미지 설명 등록 */
INSERT INTO G_LCLGV_HNR_USER_RWRD_IMG_EXPLN
	(
		lclgv_cd
		, IMG_EXPLN
		, IMG_SEQ
		, FRST_RGTR_ID
	)
	VALUES

	(
		#{lclgvCd}
		, #{prjImageExplain.prjsValues}
		, #{prjImageExplain.prjsIndexes}
		, #{frstRgtrId}
	)

mapper.delete:
/* saleson.shop.lclgvHnrUser.LclgvHnrUserMngMapper.deleteImgDescList 지자체 명예 사용자 이미지 설명 삭제 */
DELETE G_LCLGV_HNR_USER_RWRD_IMG_EXPLN
WHERE lclgv_cd = #{lclgvCd}

mapper.select:
/** saleson.shop.lclgvHnrUser.LclgvHnrUserMngMapper.lclgvHnrUserViewHist 기부혜택증 열람현황 조회 */
SELECT ROW_NUMBER() OVER(ORDER BY AAA.LCLGV_CD ASC, AAA.USER_NAME ASC) AS ROW_NUMBER, AAA.* FROM ( SELECT AA.VIEW_YM, AA.USER_ID, AA.LCLGV_CD, AA.VIEW_CNT, crypto_dec('normal',B.USER_NAME ,'',0) AS USER_NAME, C.UPPER_LOCGOV_NM , C.UPPER_LOCGOV_CODE, C.LOCGOV_NM AS LCLGV_CD_NM FROM ( SELECT --A.VIEW_DT , TO_CHAR(A.VIEW_DT, 'YYYY-MM-DD') AS VIEW_YM, A.USER_ID , A.LCLGV_CD, COUNT(*) AS VIEW_CNT FROM OP_HONOR_VIEW_HIST A WHERE 1=1
AND A.VIEW_DT >= CONCAT(#{startDate}, '000000')
AND A.VIEW_DT <= CONCAT(#{endDate}, '235959')
GROUP BY TO_CHAR(A.VIEW_DT, 'YYYY-MM-DD'), A.USER_ID, A.LCLGV_CD ) AA INNER JOIN OP_USER B ON AA.USER_ID = B.USER_ID INNER JOIN G_LOCGOV C ON AA.LCLGV_CD = C.LOCGOV_CODE ) AAA WHERE 1=1
AND AAA.USER_NAME LIKE '%' || #{userName} || '%'
AND AAA.LCLGV_CD = #{lclgvCd}
AND AAA.UPPER_LOCGOV_CODE = #{upperLocgovCode}

/** saleson.shop.lclgvHnrUser.LclgvHnrUserMngMapper.lclgvHnrUserViewHistCnt 기부혜택증 열람현황 카운트 조회 */ SELECT COUNT(*) FROM ( SELECT AAA.* FROM ( SELECT AA.VIEW_YM, AA.USER_ID, AA.LCLGV_CD, AA.VIEW_CNT, crypto_dec('normal',B.USER_NAME ,'',0) AS USER_NAME, C.UPPER_LOCGOV_NM , C.UPPER_LOCGOV_CODE, C.LOCGOV_NM AS LCLGV_CD_NM FROM ( SELECT TO_CHAR(A.VIEW_DT, 'YYYY-MM-DD') AS VIEW_YM, A.USER_ID , A.LCLGV_CD, COUNT(*) AS VIEW_CNT FROM OP_HONOR_VIEW_HIST A WHERE 1=1
AND A.VIEW_DT >= CONCAT(#{startDate}, '000000')
AND A.VIEW_DT <= CONCAT(#{endDate}, '235959')
GROUP BY TO_CHAR(A.VIEW_DT, 'YYYY-MM-DD'), A.USER_ID, A.LCLGV_CD ) AA INNER JOIN OP_USER B ON AA.USER_ID = B.USER_ID INNER JOIN G_LOCGOV C ON AA.LCLGV_CD = C.LOCGOV_CODE ) AAA WHERE 1=1
AND AAA.USER_NAME LIKE '%' || #{userName} || '%'
AND AAA.LCLGV_CD = #{lclgvCd}
AND AAA.UPPER_LOCGOV_CODE = #{upperLocgovCode}
)
